package com.lamggm.rospocket;
import java.io.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class RobotFullBundleTest {
 static byte[] bundle(String geometry)throws Exception{byte[] glb=RobotGlbNormalsTest.fixture("");JSONObject j=new JSONObject().put("schema",2).put("geometry",geometry).put("robot_name","robo_real").put("description_sha256",RobotGlb.sha(RobotDescriptionTest.SMALL.getBytes(StandardCharsets.UTF_8))).put("meshes",new JSONArray().put(new JSONObject().put("uri",RobotAssetBundleTest.URI).put("file","mesh.glb").put("sha256",RobotGlb.sha(glb))));ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){z.putNextEntry(new ZipEntry("manifest.json"));z.write(j.toString().getBytes(StandardCharsets.UTF_8));z.closeEntry();z.putNextEntry(new ZipEntry("mesh.glb"));z.write(glb);z.closeEntry();}return b.toByteArray();}
 @Test public void fullCadMustNotSilentlyFallThroughToMissingGeometryOnNonGlDevice()throws Exception{RobotModelView v=new RobotModelView(RuntimeEnvironment.getApplication());IllegalArgumentException e=assertThrows(IllegalArgumentException.class,()->v.setModel(RobotDescription.parse(RobotDescriptionTest.SMALL),RobotAssetBundle.decode(bundle("full"))));assertTrue(e.getMessage().contains("OpenGL"));}
 @Test public void explicitFullFormatProvidesIndexedMeshAndExactDescriptionBinding()throws Exception{RobotAssetBundle a=RobotAssetBundle.decode(bundle("full"));assertTrue(a.fullGeometry());assertTrue(a.hasMesh(RobotAssetBundleTest.URI));assertNotNull(a.fullMesh(RobotAssetBundleTest.URI));assertNull(a.triangles(RobotAssetBundleTest.URI));assertTrue(a.matches(RobotDescription.parse(RobotDescriptionTest.SMALL)));assertFalse(a.matches(RobotDescription.parse(RobotDescriptionTest.SMALL+" ")));assertEquals(1,a.meshCount());assertThrows(IllegalArgumentException.class,()->RobotAssetBundle.decode(bundle("unknown")));}
}
